@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : int
}

class ScientificArticle {
  + DOI : string
  + title : string
}

abstract class PeerReviewedPaper {
  + citationCount : int
}

class TechnicalReport {}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

class AuthorPosition {
  + position : int
}

class Reviewer {
  + reviewerID : int
}

Person "1" -- "0..*" ResearchInstitution : worksFor
Person "1" -- "0..*" ScientificArticle : author
Person "1" -- "0..*" ScientificArticle : reviewer
ScientificArticle "1" *-- "1..*" AuthorPosition
AuthorPosition "1" -- "1" Person
ScientificArticle "1" *-- "0..*" Reviewer
Reviewer "1" -- "1" Person

PeerReviewedPaper --|> ScientificArticle
TechnicalReport --|> ScientificArticle

TechnicalReport "0..*" -- "1" ResearchInstitution : publishedBy
PeerReviewedPaper "0..*" -- "1" Journal : publishedIn

Publisher "1" -- "1..*" Journal
ResearchInstitution "0..*" -- "0..*" Journal : subscribesTo

@enduml

